package Loop;

public class NormalForLoop {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		
		int i;
		
		//For Reverse the Value
		for (i=10;i>=0;i--) {
		
			System.out.println("Value of i is: " + i);
			
		}
		
		
		for (int j=0;j<=10;j++) 
		{		
			System.out.println("Value of j is: " + j);
			
		}
		
		
	}

}
